using FluentValidation;
namespace FintechApp.Requests.ReferralRegistration { public class CreateReferralRegistrationRequest { public int UserID { get; set; } public string MobileNumber { get; set; } = string.Empty; public string ReferralCode { get; set; } = string.Empty; public int CreatedByUserID { get; set; } public bool IsBenefitUtilize { get; set; } public decimal ReferralAmount { get; set; } } public class CreateReferralRegistrationRequestValidator : AbstractValidator<CreateReferralRegistrationRequest> { public CreateReferralRegistrationRequestValidator() { RuleFor(x => x.UserID).GreaterThan(0); } } }
